    "slug": "multi-cultural-istanbul-galata-tower-fener-and-balat-golden-horn-by-ferry",
    "title": "Multi Cultural Istanbul: Galata Tower - Fener and Balat - Golden Horn by Ferry",
    "code": null,
    "summary": "We have a passion for uncovering this unique city’s lesser known historical treasures on foot.",
    "description": "We have a passion for uncovering this unique city’s lesser known historical treasures on foot. Our tour starts with imposing Galata Tower which is overlooking to beauties of Bosphorus and the Old-City. We take you off the major tourist trail to multi-cultural Fener, Balat and Ayvansaray. These are the old Istanbul neighborhoods where Constantinople officially ends which means we admire surviving city walls of Byzantines and discover historic churches, mosques, synagogues, traditional houses and even the remnants of a palace. Finish off our tour with a relaxing ferry journey along the Golden Horn.",
