    "daysList": [
      {
        "id": "09e53bdd-dd33-4c2c-93a7-13ec97842f27",
        "tour_id": "4980f6f8-b5dd-4874-aa7b-f63c535b9615",
        "day_number": 1,
        "title": "Basilica Cistern",
        "body": "This spacious Roman built cistern shows off impressive Roman engineering was commissioned by Emperor Justinian, largest surviving Byzantine cistern in Istanbul and has been backdrop for many movies over time."
      },
      {
        "id": "53c03961-620a-4016-8283-d69270eb1b8d",
        "tour_id": "4980f6f8-b5dd-4874-aa7b-f63c535b9615",
        "day_number": 2,
        "title": "Sultanahmet Mosque ( Blue Mosque )",
        "body": "Sultan Ahmed Mosque, known as the Blue Mosque by many tourists because of its bluish interior decoration( blue tiles surrounding the walls of interior design), is the most important mosque of Istanbul standing next to the Byzantine Hippodrome in the old city center.."
      },
      {
        "id": "6b08fa4d-1b03-4e24-b1b9-74562e4cc4e1",
        "tour_id": "4980f6f8-b5dd-4874-aa7b-f63c535b9615",
        "day_number": 3,
        "title": "Hippodrome",
        "body": "The Hippodrome of Constantinople was a circus that was the sporting and social center of Constantinople. Today it is a square with a few fragments of the original structure surviving. Monuments decorating the Hippodrome include the 3500-year-old Egyptian Obelisk, Serpentine Column..."
      },
      {
        "id": "09ca689e-14a6-4f69-b6bc-9759c7686a3a",
        "tour_id": "4980f6f8-b5dd-4874-aa7b-f63c535b9615",
        "day_number": 4,
        "title": "Hagia Sophia Mosque (Pass by)",
        "body": "Began its life as a church in 532 AD, converted into a mosque after the Turkish conquest of Constantinople in 1453 and now a museum since 1935. By general consensus, it is the most important Byzantine structure and one of the world’s great monuments built under the direction of the Byzantine emperor Justinian I. Part of the UNESCO World Heritage site in Istanbul and famous for its lofty interior, stunning surviving mosaics and the massive dome..."
      },
      {
        "id": "d500b189-5d30-45f3-bff9-10c5a0686e9b",
        "tour_id": "4980f6f8-b5dd-4874-aa7b-f63c535b9615",
        "day_number": 5,
        "title": "Sultanahmet Square",
        "body": "This beautiful square and a great place to make a stop, relax and take photos of Hagia Sophia and the Blue Mosque. \"Sultan Ahmet Center\", the heart of the \"Old City\" from where the Byzantine and Ottoman Empires were ruled"
      },
      {
        "id": "8278da5b-011f-47fd-9275-4979f65c53d2",
        "tour_id": "4980f6f8-b5dd-4874-aa7b-f63c535b9615",
        "day_number": 6,
        "title": "Kapalı Carşı ( Grand Bazaar )",
        "body": "Istanbul's Grand Bazaar is high on most tourists' itineraries, and for a good reason. This enormous site is the largest covered market in the world with 61 covered streets and over 4,000 shops on a total area of 30,700 m², attracting between 250,000 and 400,000 visitors daily..."
      },
      {
        "id": "4fe97c08-30eb-4384-bfb6-d576236ceeec",
        "tour_id": "4980f6f8-b5dd-4874-aa7b-f63c535b9615",
        "day_number": 7,
        "title": "*️⃣↘️",
        "body": "* Seen from outside / Pass by"
      }
    ],
