    "id": "8d2caa23-e9d9-45a5-a8f4-9dc3ab955c74",
    "slug": "istanbul-modern-city-walking-taksim-to-galata-with-secret-passages",
    "title": "Istanbul Modern City Walking: Taksim to Galata With Secret Passages",
    "code": null,
    "summary": "This tour takes you into the heart of the modern section of Istanbul to be shown the unmistakable icons as well as the hard-to-find secret spots that make Beyoğlu so captivating.",
    "description": "This tour takes you into the heart of the modern section of Istanbul to be shown the unmistakable icons as well as the hard-to-find secret spots that make Beyoğlu so captivating. Veer away from the hustle and bustle of Istiklal Avenue to discover the beautiful side streets and historical passages that get missed by tourists and Turks alike. See the Pera district through a local’s eyes and learn about its cosmopolitan history. Area is also famous across Istanbul for its outstanding street food but discovering good eateries in a big city is not always easy. Not to worry, as we stroll Istiklal Avenue, your guide will point out best local eating places, cafés and bars, as well as show you the main points of interest along the way. \n\n• Let your guide take you to the hidden backstreets and passages of Beyoğlu\n• Discover the secret haunts of locals, best local eating places and bars\n• Sample top-notch Beyoğlu Chocolate suggested by your guide \n• Enjoy the relaxed pace of a walking tour",
