    "daysList": [
      {
        "id": "1e1d31ca-bdfc-4601-aafd-eb02e02ab52d",
        "tour_id": "6437435b-4c98-4077-bb5d-6dbacfcfaf53",
        "day_number": 1,
        "title": "istanbul Old Town & Traditional Ottoman Tastes",
        "body": "Merhaba ( Hello ) and Hoşgeldiniz ( Welcome ) to istanbul. Today we are looking forward to see you in the lobby at 1 pm. Your Guide will meet you with full of energy.\n\nAfter, you will starts old town City Tour With Your Professional Tour Guide. Your guide will show you historic city's hidden gems, including the amazing Blue Mosque, Hippodrome and listen amazing stories and myths...\n\nYou will learn lots about Ottoman life in TOPKAPI PALACE...\n\nYou will enjoy a traditional welcome dinner, where your guide will introduce you to some of the region’s most famous local dishes, including one of the finest specialties from Ottoman cuisine.\n\nOvernight in Istanbul\n\nAccomodation : Wyndham Istanbul old town or Similar"
      },
      {
        "id": "603368ed-78ab-4d4f-97ad-58ff7a0b826d",
        "tour_id": "6437435b-4c98-4077-bb5d-6dbacfcfaf53",
        "day_number": 2,
        "title": "Gaziantep & Famous Antep Baklava",
        "body": "This Morning we fly to Gaziantep city where the most famous baklava invented. Visit the world-renowned Zeugma Mosaic Museum, home to some of the most stunning Roman mosaics ever discovered, including the iconic “Gypsy Girl.” This museum offers a fascinating glimpse into the region’s ancient past. Wander through the charming alleys of the old bazaar area, including Bakırcılar Çarşısı (Coppersmith Bazaar), where you can watch artisans at work and shop for handcrafted souvenirs. For dinner, indulge in Gaziantep’s legendary cuisine at İmam Çağdaş, one of the most famous kebab restaurants in the country. Try local specialties such as Ali Nazik kebab, lamb skewers, and freshly baked lahmacun.\n\nOvernight in Gaziantep\n\nAccomodation : Hilton Garden inn or Similar"
      },
      {
        "id": "d811f296-26d2-4293-9f7f-2db08bb77c4d",
        "tour_id": "6437435b-4c98-4077-bb5d-6dbacfcfaf53",
        "day_number": 3,
        "title": "Adiyaman & Local Family Lunch",
        "body": "Enjoy a warm local family lunch in a village before continuing your journey to Mount Nemrut. In Adıyaman, you’ll experience authentic daily life as we visit a local Kurdish family in their home. Share a traditional meal, learn about their culture, and discover the stories behind their special dishes. Afterward, we drive to Mount Nemrut to see the giant stone heads and Watch the sun set over the colossal statues of this UNESCO World Heritage Site at 2,000 m.  \n\nOvernight in Adıyaman.\n\nAccommodation : Ramada by Wyndham Adiyaman or Similar"
      },
      {
        "id": "11f44968-bf45-4ddd-b81a-19ec06f235c1",
        "tour_id": "6437435b-4c98-4077-bb5d-6dbacfcfaf53",
        "day_number": 4,
        "title": "Göbeklitepe Temple & Traditional Sıra Gecesi Activity",
        "body": "Explore Göbeklitepe, the world’s oldest known temple complex and a UNESCO site. Visit the Şanlıurfa Archaeology Museum and the Mosaic Museum, home to the famous “Urfa Man” statue. Get ready this evening for enjoyable activity. Sıra Gecesi is a traditional social gathering from Şanlıurfa, combining music, food, and friendship into one unforgettable night.\n\nOvernight in sanliurfa\n\nAccommodation : Hilton Garden inn or similar"
      },
      {
        "id": "f0b20022-0ca3-49a5-85b9-e22975e562ca",
        "tour_id": "6437435b-4c98-4077-bb5d-6dbacfcfaf53",
        "day_number": 5,
        "title": "Şanlıurfa Old Town & Urfa Kebap Night",
        "body": "Head to Karahantepe and Soğmatar, mysterious ancient settlements linked to early civilizations. Overnight in Şanlıurfa. Visit the Şanlıurfa Archaeology Museum and the Mosaic Museum, home to the famous “Urfa Man” statue.\n\nToday you will try Urfa Kebab – The iconic local kebab made from seasoned minced meat grilled over charcoal. Less spicy than some other regional kebabs but deeply flavorful. Enjoy your meal.\n\nOvernight in Sanliurfa\n\nAccommodation : Hilton Garden inn or similar"
      },
      {
        "id": "264c7bc2-202d-4457-a8ea-7bac83a1ec11",
        "tour_id": "6437435b-4c98-4077-bb5d-6dbacfcfaf53",
        "day_number": 6,
        "title": "Mardin Old Town & Famous Turkish ice Cream",
        "body": "Today drive to Diyarbakir city to see unesco city walls and continue to Mesopotamia. After Hotel check-in, you will have orientation walk with your guide. Then treat yourself to delicious baklava served with traditional Turkish ice cream — a perfect way to end your journey with a sweet delight.\n\nOvernight in Mardin\n\nAccommodation : Kasım Efendi Konağı Boutique hotel or similar"
      },
      {
        "id": "a52cb1d0-f445-484a-a3d9-1997fa17887f",
        "tour_id": "6437435b-4c98-4077-bb5d-6dbacfcfaf53",
        "day_number": 7,
        "title": "Mardin & Traditional Mardin Tastes",
        "body": "Stroll through the atmospheric Old Town of Mardin with its golden stone houses. Explore Dara Ancient City, an important Byzantine site, and Deyrulzafaran Monastery, a spiritual center of the Syriac Orthodox Church.\n\nWe have a reservation for one of the popular traditional restaurant. You will have Mardin's signature meals like Kaburga Dolması Stuffed lamb ribs filled with rice, almonds, spices. Irok (Stuffed Kibbeh) and more interesting foods. Before we finish our experience, do not forget to have Kurdish traditional coffee Mırra.\n\nOvernight in Mardin\n\nAccommodation : Kasım Efendi Konağı Boutique hotel or similar"
      },
      {
        "id": "b0d94f9e-d2c8-47fc-9ac5-7375a4ce32fa",
        "tour_id": "6437435b-4c98-4077-bb5d-6dbacfcfaf53",
        "day_number": 8,
        "title": "Van & Traditional Local Dinner",
        "body": "Today we have long driving hours. Early Drive to scenic boat trip to Akdamar Island, where you will explore the beautifully preserved 10th-century Armenian Church of the Holy Cross set against the stunning backdrop of Lake Van. Afterwards, return to the mainland and visit the imposing Van Castle, offering breathtaking panoramic views over the lake and surrounding landscape. Continue your journey to Tatvan, a peaceful town nestled along the shores of Lake Van.\n\nOvernight in Van\n\nAccommodation : Double Tree by Hilton or Similar"
      },
      {
        "id": "7a1eb318-d0af-4188-bdff-3c8032043dce",
        "tour_id": "6437435b-4c98-4077-bb5d-6dbacfcfaf53",
        "day_number": 9,
        "title": "Kars & Famous Cheese Taste",
        "body": "Depart after delicious breakfast and Visit Ishak Paşa Palace on the way, an Ottoman-Persian architectural masterpiece, with views of Mount Ararat.\n\nWe will visit a cheese shop. Kars is famous for its Gravyer cheese (Swiss-style, nutty, aged) and rich Kars kaşar. The high-altitude pastures give the milk a unique aroma.\n\nOvernight in Kars\n\nAccommodation : Katarina Palace Hotel or Similar"
      },
      {
        "id": "f541f49d-fc91-4861-b11e-3fb811afb692",
        "tour_id": "6437435b-4c98-4077-bb5d-6dbacfcfaf53",
        "day_number": 10,
        "title": "Kars Ani Ruins & Fly back to istanbul",
        "body": "A city where the echoes of empires still linger in its streets. Discover Kars’s fascinating blend of Russian-era architecture, Ottoman heritage, and vibrant local culture. \n\nThis Afternoon, journey to the awe-inspiring Ani Ruins, the once-glorious medieval capital known as the “City of 1,001 Churches.” Perched dramatically on the border overlooking the Arpaçay River, Ani’s silent stone walls and towering cathedrals whisper tales of Silk Road traders, ancient kingdoms, and lost civilizations. Stroll among its hauntingly beautiful remains, from the grand Cathedral of Ani to the Church of the Redeemer, and feel the weight of history beneath your feet.\n\nWe have a afternoon flight to istanbul and Tour Ends in istanbul airport"
      }
    ],
