    "id": "32aa3df5-92bb-4f5f-8f20-a4df3f242746",
    "slug": "hike-bike-kayak-in-kas-turkey",
    "title": "Kaş : Hike, Bike, Kayak & Dive",
    "code": "HBK ",
    "summary": "Explore Kaş: Nature, History, and the Sea – A Perfect Mediterranean Escape",
    "description": "Explore Kaş: Nature, History, and the Sea – A Perfect Mediterranean Escape\n\nNestled along the stunning turquoise coast of Turkey, Kaş offers the perfect mix of adventure, culture, and relaxation. Start your journey with trade two wheels for a paddle and head out on a kayaking adventure over the sunken city of Kekova. Glide across crystal-clear waters as you pass over ancient ruins submerged just beneath the surface, and stop by the charming village of Kaleköy (Simena), only accessible by boat or foot. It’s a peaceful, unforgettable way to connect with the region’s deep history. Bike ride through the scenic hills and coastline, where olive groves, ancient ruins, and panoramic sea views await at every turn. Whether you're cycling through peaceful villages or challenging yourself on mountain paths, it's a refreshing way to experience the natural beauty of the region. For a journey even further back in time, visit the ancient Lycian sites of Letoon and Xanthos. These UNESCO World Heritage Sites are home to stunning temple ruins, grand theaters, and mysterious inscriptions. Walking among the stones, you’ll feel the echoes of civilizations that flourished thousands of years ago. To cool off, head inland to Saklıkent Gorge, one of the deepest canyons in Turkey. Walk through the icy mountain stream, splash through narrow passages carved by centuries of water, or just relax in one of the riverside cafes with your feet in the water. It’s the perfect spot to recharge and escape the summer heat.\n\nCap off your Kaş adventure with a full-day boat trip along the coast. Sail to hidden bays, swim in secluded coves, and snorkel above vibrant underwater life. Enjoy a freshly prepared Turkish lunch onboard, bask in the sun, and let the rhythm of the waves carry your worries away. It’s the ultimate blend of leisure and exploration.\n\nDay By Day itinerary\n\nDay 1. Free Arrival Transfer & Welcome Meeting\n\nDay 2. Sea Kayaking at Kekova Area\n\nDay 3. Biking in Kaş\n\nDay 4. Hike in Lycian Way ( 15 km )\n\nDay 5. Letoon Santhos ( unesco ) and Saklıkent Gorge\n\nDay 6. Hike Lycian Way & Full Day Boat Trip\n\nDay 7. Departure",
