    "daysList": [
      {
        "id": "d17e038f-82f7-4aca-937a-8f2d70d430d8",
        "tour_id": "32aa3df5-92bb-4f5f-8f20-a4df3f242746",
        "day_number": 1,
        "title": "Airport to Kaş - Welcome Day",
        "body": "Arrive to Dalaman Airport. Drive to charming coastal town of Kaş and settle into your accommodation. Take time to explore the harbor, local boutiques, and ancient theater. In the evening, meet your guide and fellow adventurers for a welcome dinner and briefing on the exciting week ahead.\n\nIncluded: Airport transfer (optional), hotel check-in, welcome dinner, orientation. Welcome meeting at 6pm and welcome dinner included.\n\nAccommodation : Payam Boutique Hotel or Similar"
      },
      {
        "id": "45eb2c9a-0e47-4b2a-b1a5-a33c1bd95450",
        "tour_id": "32aa3df5-92bb-4f5f-8f20-a4df3f242746",
        "day_number": 2,
        "title": "Kaş - Sea kayaking - Paddle Through History",
        "body": "Head to the calm turquoise waters of Kekova for a guided sea kayaking tour over the sunken city of Simena. Glide past Lycian tombs, ancient ruins, and charming island villages. Swim in hidden coves and enjoy a local lunch by the sea. ( included )\n\nAccommodation : Payam Boutique Hotel or Similar\n\nHighlights:\n\nPaddle over submerged ruins\n\nVisit Simena Castle (optional hike)\n\nSnorkeling break in crystal-clear waters"
      },
      {
        "id": "f2878cb3-f96f-4f3a-a737-82454fe325d9",
        "tour_id": "32aa3df5-92bb-4f5f-8f20-a4df3f242746",
        "day_number": 3,
        "title": "Kaş - Mountain Biking in Kaş – Rugged, Real, and Wildly Beautiful",
        "body": "Get off the beaten path with a mountain biking tour through pine forests, mountain villages, and panoramic viewpoints. This route blends dirt trails and quiet rural roads, offering a thrilling yet accessible ride.\n\nAccommodation : Payam Boutique Hotel or Similar\n\nHighlights:\n\nScenic countryside and sea views\n\nLocal tea house stop in a traditional village\n\nOption to ride down to Limanağzı beach"
      },
      {
        "id": "a7c91ffd-d142-4281-bc78-4507133e0713",
        "tour_id": "32aa3df5-92bb-4f5f-8f20-a4df3f242746",
        "day_number": 4,
        "title": "Kaş Famous Diving Experience – Discover the Underwater World",
        "body": "Today, explore why Kaş is considered one of the best diving destinations in Turkey. With its crystal-clear Mediterranean waters, rich marine life, and fascinating underwater archaeological sites, Kaş offers an unforgettable scuba diving adventure.\n\nAccommodation : Payam Boutique Hotel or Similar\n\nDive Program:\n\n2 guided dives (for certified divers)\n\nIntroductory dive option available for beginners\n\nSmall groups with experienced dive masters\n\nAll equipment included\n\nBetween dives, relax on the boat, swim in turquoise waters, and enjoy the stunning coastal views of Kaş.\n\nDifficulty: Easy to Moderate (no experience required for discovery dive)\n\nOvernight in Kaş."
      },
      {
        "id": "d1751744-a4c0-4bc5-a498-c3c758cd51e7",
        "tour_id": "32aa3df5-92bb-4f5f-8f20-a4df3f242746",
        "day_number": 5,
        "title": "Kaş - Letoon, Xanthos & Saklıkent Gorge (UNESCO & Natural Wonders)",
        "body": "Discover the ancient Lycian capital Xanthos and the sacred city of Letoon, both UNESCO World Heritage Sites. After exploring the ruins, cool off with a walk through Saklıkent Gorge, one of Turkey’s deepest canyons.\n\nAccommodation : Payam Boutique Hotel or Similar\n\nHighlights:\n\nWalk in icy mountain waters\n\nExplore temples, theaters, and tombs\n\nLunch by the river"
      },
      {
        "id": "f827a710-35e8-4531-ad4d-da04e6a7e1c7",
        "tour_id": "32aa3df5-92bb-4f5f-8f20-a4df3f242746",
        "day_number": 6,
        "title": "Kaş - Hike from Apollonia to Aperlai & Boat Trip Adventure",
        "body": "Begin with a beautiful Lycian hike from the hilltop ruins of Apollonia to the hidden bay of Aperlai. After arriving at the sea, enjoy a relaxing boat trip with swimming stops and a freshly prepared lunch on board.\n\nAccommodation : Payam Boutique Hotel or Similar\n\nHighlights:\n\nRemote Lycian ruins\n\nForested trails and wild herbs\n\nBoat cruise in crystal-clear waters"
      },
      {
        "id": "a12cb21a-2ed4-4d75-b26d-a02057b43a9f",
        "tour_id": "32aa3df5-92bb-4f5f-8f20-a4df3f242746",
        "day_number": 7,
        "title": "Kaş - Departure Day",
        "body": "After breakfast, say goodbye to your guide and group. Take home unforgettable memories of ancient trails, wild landscapes, and turquoise waters.\n\nAs you embark on your journey home, may the memories you've gathered during our trip stay with you like treasures in your heart.\nSafe travels and may your path ahead be as enriching and joyful as your time here. Until we meet again, cherish the moments and carry a piece of Turkey's spirit with you wherever you go.\nFarewell and best wishes for your future adventures!\n\nWarm regards\nAGT GROUP LLC TEAM"
      }
    ],
