    "daysList": [
      {
        "id": "0eb2bf45-9657-446b-985f-389c73c86729",
        "tour_id": "1e90f326-7aec-4c07-9ebe-56787e59a3b7",
        "day_number": 1,
        "title": "Old Town Visit & Traditional Ottoman Tastes",
        "body": "Merhaba ( Hello ) and Hoşgeldiniz ( Welcome ) to istanbul. Today we are looking forward to see you in the lobby at 1 pm. Your Guide will meet you with full of energy.\n\nAfter, you will starts old town City Tour With Your Professional Tour Guide. Your guide will show you historic city's hidden gems, including the amazing Blue Mosque, Hippodrome and listen amazing stories and myths...\n\nYou will learn lots about Ottoman life in TOPKAPI PALACE...\n\nYou will enjoy a traditional welcome dinner, where your guide will introduce you to some of the region’s most famous local dishes, including one of the finest specialties from Ottoman cuisine.\n\nAccomodation : Wyndham Istanbul old town or Similar"
      },
      {
        "id": "b89a49bc-6851-44c2-89f1-b41b3e8fc78f",
        "tour_id": "1e90f326-7aec-4c07-9ebe-56787e59a3b7",
        "day_number": 2,
        "title": "Gallipoli & Meyhane Food Culture",
        "body": "Today we sett off from istanbul to visit famous Gallipoli Anzac site. After a 4 hours short driving, We reach the site of Gallipoli's key Battlefields, Memorials and cemeteries. Reflect at an Anzac cove, Lone Pine cemetery and Chunuk Bair, while gaining deep insights into bravery and sacrifice of Anzac troops through expert commentary. This journey offers a respectful  and moving tribute to a significant chapter in history.\n\nToday you will experience Meyhane culture which is a central part of traditional Ottoman and modern Turkish social life, especially in Istanbul and coastal cities.\n\nOvernight in Canakkale\n\nAccommodation : DoubleTree by Hilton or Similar"
      },
      {
        "id": "d90c35cf-7af3-4a71-8cd1-8d448edac014",
        "tour_id": "1e90f326-7aec-4c07-9ebe-56787e59a3b7",
        "day_number": 3,
        "title": "Legendary Troy & Famous Turkish Cheese Taste",
        "body": "Today we will depart from Çanakkale and head to Ephesus. Our first stop will be the historic site of Troy and Archeologican Museum, where you will explore the legendary ruins of this ancient city. \n\nToday at lunch , We will try Ezine cheese (Ezine peyniri) is one of Türkiye’s most famous and protected cheeses. Ezine cheese , some bread and Traditional Turkish tea is one of the best.\n\nOvernight in Selcuk.\n\nAccomodation : Celsus Boutique Hotel or Similar"
      },
      {
        "id": "13d196aa-9621-47e5-9e44-45fce4c0fd16",
        "tour_id": "1e90f326-7aec-4c07-9ebe-56787e59a3b7",
        "day_number": 4,
        "title": "Ancient Ephesus & Cooking Class",
        "body": "Begin with a visit to the grand Library of Celsus, visit St.john church an iconic symbol of the city's former glory. Explore the impressive Great Theater and stroll through the Historic Arcadian way. Marvel at the well-preserved Temple of Hadrian and the remains of the Roman Baths. Conclude with a visit to the Terrace Houses, showcasing the opulent lifestyle of Ephesus' elite. This immersive tour offers a deep dive into the rich history and architectural splendor of one of the best-preserved ancient cities. \n\nToday we have Turkish Cooking Class. Are you Ready for it ? Let cook with local chef and have a great dinner all together.\n\nOvernight in Selcuk\n\nAccommodation : Celsus Boutique Hotel or Similar"
      },
      {
        "id": "7471abd6-9d54-4ec7-9438-2b333fd3d3f9",
        "tour_id": "1e90f326-7aec-4c07-9ebe-56787e59a3b7",
        "day_number": 5,
        "title": "Antalya & Pamukkale",
        "body": "Experience the natural wonder of Pamukkale with our detailed itinerary. Start your day exploring the stunning white terraces of Pamukkale, formed by thermal mineral waters that create cascading pools. Enjoy s soak in the warm, mineral-rich waters of the thermal pools, taking in the breathtaking views of the surrounding landscape. Next, visit the ancient city of Hierapolis, where you can wander through the well-preserved ruins, including the ancient theater and Roman baths.\n\nOvernight in Antalya\n\nAccommodation : Ruin Adalia Boutique Hotel or Similar"
      },
      {
        "id": "35e106b8-4417-40e0-99de-b37395df4bb4",
        "tour_id": "1e90f326-7aec-4c07-9ebe-56787e59a3b7",
        "day_number": 6,
        "title": "Antalya & Mediterranian Sea Food Experience",
        "body": "This morning, we begin our exploration of the Old Town with a guided city tour. Our first stop is Hadrian’s Gate, one of the most iconic landmarks of the city. From there, we take a pleasant walk to the Roman Necropolis Museum, where you will gain insight into ancient burial traditions and local history.\n\nAlong the way, we’ll enjoy a taste of delicious Turkish ice cream before continuing to discover the remains of the Old Seljuk civilization settlements. After the guided visits, you will have some free time to wander through the charming streets and enjoy shopping at your own pace.\n\nIn the evening, get ready for a memorable sunset dinner, the perfect way to end a day full of history and culture.\n\nOvernight in Antalya\n\nAccomodation : Ruin Adalia Boutique Hotel or Similar"
      },
      {
        "id": "94403bf2-d3fb-46eb-bc6d-f0f5bd7bb7ab",
        "tour_id": "1e90f326-7aec-4c07-9ebe-56787e59a3b7",
        "day_number": 7,
        "title": "Flight Back to istanbul & Tour ends",
        "body": "Today we fly back to istanbul in the morning and tour ends at the airport\n\nAs you embark on your journey home, may the memories you're gathered during our trip stay with you like treasures in your heart.\n\nOur team will ensure you have all the details for your onward journey, whether you're heading to the airport or continuing your travels.  Safe travels and thank you for joining us on this incredible adventure !\n\nFarewell and Best wishes for your future adventures!\n\nWe wish to see you again in another great Atlas Global Tours."
      }
    ],
