    "daysList": [
      {
        "id": "dbe6f9dc-ae0b-46e6-bbfe-dd68551f8c48",
        "tour_id": "25d9f18c-e79f-4e38-a9a3-4761533869d6",
        "day_number": 1,
        "title": "istanbul Old Town & Traditional Ottoman Tastes",
        "body": "Welcome to Türkiye! Your adventure begins in the captivating city of Istanbul, celebrated for its rich history and unique location straddling two continents. Meet your tour leader and fellow travelers at 1:00 pm for a welcome meeting in the hotel and trip briefing.\n\nAfter introductions, embark on a guided exploration of Istanbul’s enchanting Old Town. Visit the Topkapı Palace, the opulent residence of Ottoman sultans; admire the architectural splendor of the Blue Mosque; and stroll through the historic Hippodrome, once the heart of Byzantine civic life. Continue to the vibrant Grand Bazaar, one of the world’s oldest and largest covered markets, filled with colorful shops and local treasures.\n\nYou will enjoy a traditional welcome dinner, where your guide will introduce you to some of the region’s most famous local dishes, including one of the finest specialties from Ottoman cuisine.\n\nOvernight in istanbul\n\nAccommodation : Wyndham old Town or Similar"
      },
      {
        "id": "ee3b507f-01f4-4ae1-8ebe-3f1d64200e5e",
        "tour_id": "25d9f18c-e79f-4e38-a9a3-4761533869d6",
        "day_number": 2,
        "title": "Gaziantep & Famous Antep Baklava",
        "body": "This Morning we fly to Gaziantep city where the most famous baklava invented. Visit the world-renowned Zeugma Mosaic Museum, home to some of the most stunning Roman mosaics ever discovered, including the iconic “Gypsy Girl.” This museum offers a fascinating glimpse into the region’s ancient past. Wander through the charming alleys of the old bazaar area, including Bakırcılar Çarşısı (Coppersmith Bazaar), where you can watch artisans at work and shop for handcrafted souvenirs. For dinner, indulge in Gaziantep’s legendary cuisine at İmam Çağdaş, one of the most famous kebab restaurants in the country. Try local specialties such as Ali Nazik kebab, lamb skewers, and freshly baked lahmacun.\n\nOvernight in Gaziantep\n\nAccomodation : Hilton Garden inn or Similar"
      },
      {
        "id": "46580a67-e923-44b2-b086-e5f27a942031",
        "tour_id": "25d9f18c-e79f-4e38-a9a3-4761533869d6",
        "day_number": 3,
        "title": "Adiyaman & Local Family Lunch",
        "body": "Enjoy a warm local family lunch in a village before continuing your journey to Mount Nemrut. In Adıyaman, you’ll experience authentic daily life as we visit a local Kurdish family in their home. Share a traditional meal, learn about their culture, and discover the stories behind their special dishes. Afterward, we drive to Mount Nemrut to see the giant stone heads and Watch the sun set over the colossal statues of this UNESCO World Heritage Site at 2,000 m.  \n\nOvernight in Adıyaman.\n\nAccommodation : Ramada by Wyndham Adiyaman or Similar"
      },
      {
        "id": "e5eaad7b-e860-42c7-908c-b6acbce5b8e8",
        "tour_id": "25d9f18c-e79f-4e38-a9a3-4761533869d6",
        "day_number": 4,
        "title": "Göbeklitepe Temple & Traditional Sıra Gecesi Activity",
        "body": "Explore Göbeklitepe, the world’s oldest known temple complex and a UNESCO site. Visit the Şanlıurfa Archaeology Museum and the Mosaic Museum, home to the famous “Urfa Man” statue. Get ready this evening for enjoyable activity. Sıra Gecesi is a traditional social gathering from Şanlıurfa, combining music, food, and friendship into one unforgettable night.\n\nOvernight in sanliurfa\n\nAccommodation : Hilton Garden inn or similar"
      },
      {
        "id": "65a8e673-b016-4bca-88f8-5e8133d95edc",
        "tour_id": "25d9f18c-e79f-4e38-a9a3-4761533869d6",
        "day_number": 5,
        "title": "Şanlıurfa Old Town & Urfa Kebap Night",
        "body": "Head to Karahantepe and Soğmatar, mysterious ancient settlements linked to early civilizations. Overnight in Şanlıurfa. Visit the Şanlıurfa Archaeology Museum and the Mosaic Museum, home to the famous “Urfa Man” statue.\n\nToday you will try Urfa Kebab – The iconic local kebab made from seasoned minced meat grilled over charcoal. Less spicy than some other regional kebabs but deeply flavorful. Enjoy your meal.\n\nAccommodation : Hilton Garden inn or similar"
      },
      {
        "id": "955cd6ab-a517-4219-946c-a5f92fff8f30",
        "tour_id": "25d9f18c-e79f-4e38-a9a3-4761533869d6",
        "day_number": 6,
        "title": "Return Flight & The Tour Ends",
        "body": "Today marks the final day of your journey. After breakfast, we’ll transfer you to sanliurfa Airport for your domestic flight back to Istanbul. We aim to secure the earliest available flight, but if morning flights are fully booked, you will be scheduled on the next available afternoon departure.\n\nThank you for visiting Türkiye and for choosing to travel with Atlas Global Tours LLC. It has been our pleasure to host you, and we hope to welcome you again on another unforgettable adventure in the future.\n\nTour ends in the airport"
      }
    ],
