    "is_featured": true,
    "is_published": true,
    "created_at": "2026-08-21T18:37:14.729282+00:00",
    "updated_at": "2026-08-22T21:23:36.147541+00:00",
    "tour_type": "multi_day",
    "duration_hours": null,
    "meeting_point": null,
    "activity_level": "3 - Active",
    "travel_style": "Spotlight",
    "best_time": "Apr–Jun & Sep–Oct",
    "meals_breakfasts": 6,
    "meals_lunches": 7,
    "meals_dinners": 6,
    "daysList": [
      {
        "id": "4f54fa6f-cfe6-4baa-97c7-f1ef4104ab5d",
        "tour_id": "650fd423-d161-4f36-a15a-28381b5e114a",
        "day_number": 1,
        "title": "Welcome to Cappadocia",
        "body": "Merhaba ( Hello ). Today we will have a Welcome meeting at 6 pm where you will meet your tour guide and fellow travelers. After the briefing, orientation walk starts in Goreme Town. Welcome dinner in Goreme town. Try delicious and famous pottery kebap\n\nMeal : Dinner optional\n\nAccommodation : Ciner hotel or similar"
      },
      {
        "id": "94c74901-55cd-47ab-9855-59f811281348",
        "tour_id": "650fd423-d161-4f36-a15a-28381b5e114a",
        "day_number": 2,
        "title": "Red & Rose Valley Hike ( 10 - 12 km )",
        "body": "Enjoy a scenic hike through Cappadocia’s beautiful Red and Rose Valleys, famous for their colorful rock formations, fairy chimneys, cave churches, and peaceful vineyard trails. Walk along winding paths and narrow canyon passages while discovering hidden chapels carved into the cliffs.\n\nTake a relaxing break at a local valley café before continuing toward the panoramic viewpoints of Red Valley, where the landscape glows with stunning shades of red and pink, especially at sunset.\n\nHiking Distance: Approx. 10–12 km\n\nAccommodation : Tas Konak Cave Hotel or Similar"
      },
      {
        "id": "302fd26a-9913-456f-99dd-1f96c22db688",
        "tour_id": "650fd423-d161-4f36-a15a-28381b5e114a",
        "day_number": 3,
        "title": "Love Valley Hike ( 8 - 10 km )",
        "body": "After breakfast, set out for a scenic nature trek through the beautiful Love Valley, famous for its towering fairy chimneys and unique volcanic rock formations. Walk along peaceful trails surrounded by vineyards, orchards, and dramatic canyon scenery while enjoying spectacular views of Cappadocia’s landscape.\n\nContinue toward Uçhisar, the highest point in Cappadocia, passing through quiet village paths and natural valleys along the way. Enjoy panoramic views of the region and explore the charming atmosphere of Uçhisar Village beneath its impressive rock castle.\n\nThis easy to moderate hike offers a perfect combination of nature, local life, and breathtaking scenery.\n\nHiking Distance : Approx. 8–10 km\n\nAccommodation : Ciner Hotel or Similar"
      },
      {
        "id": "3752e23d-dea4-4422-85f6-208079f1eb34",
        "tour_id": "650fd423-d161-4f36-a15a-28381b5e114a",
        "day_number": 4,
        "title": "Ihlara Valley Nature & River Hike ( 12 - 14 km )",
        "body": "Drive to the stunning Ihlara Valley, one of Cappadocia’s most beautiful canyon landscapes. Enjoy a scenic trek along the Melendiz River surrounded by lush greenery, towering cliffs, and peaceful nature far from the crowds.\n\nWalk through the canyon while discovering ancient rock-cut churches, hidden cave dwellings, and frescoed chapels carved into the valley walls by early Christian communities centuries ago. Along the route, enjoy relaxing riverside breaks at local cafés set beside the flowing river.\n\nThis refreshing hike combines nature, history, and local atmosphere, offering a completely different side of Cappadocia.\n\nHiking Distance: Approx. 12–14 km\n\nAccommodation : Ciner Hotel or Similar"
      },
      {
        "id": "f6093eda-ca72-4e63-8092-3434aa6832b9",
        "tour_id": "650fd423-d161-4f36-a15a-28381b5e114a",
        "day_number": 5,
        "title": "Pigeon Valley Hike ( 6 - 8 km )",
        "body": "Continue with a scenic hike through Pigeon Valley, famous for its panoramic views, cave dwellings, and traditional pigeon houses carved into the cliffs. Walk along peaceful valley trails surrounded by unique rock formations and beautiful Cappadocian landscapes stretching between Uçhisar and Göreme.\n\nThis experience offers a perfect blend of Cappadocia’s rich history, local culture, and stunning natural scenery.\n\nHiking Distance: Approx. 6–8 km\n\nAccommodation : Ciner Hotel or Similar"
      },
      {
        "id": "9024bab0-8087-416c-9db1-430185605a66",
        "tour_id": "650fd423-d161-4f36-a15a-28381b5e114a",
        "day_number": 6,
        "title": "Ortahisar Hidden Valley Hike ( 7 - 9 km )",
        "body": "After breakfast, explore the authentic village atmosphere of Ortahisar, one of Cappadocia’s most traditional and less-visited towns. Walk through quiet stone streets, local neighborhoods, and scenic countryside paths beneath the impressive Ortahisar Rock Castle.\n\nContinue with a peaceful hike through hidden valleys away from the crowds, surrounded by dramatic rock formations, cave dwellings, orchards, and small local farms. Along the way, enjoy beautiful panoramic viewpoints and experience the untouched side of Cappadocia’s natural landscape.\n\nThis easy to moderate hike offers a perfect combination of local culture, nature, and off-the-beaten-path discovery. Hiking Distance: Approx. 7–9 km.\n\nHiking Distance: Approx. 7–9 km\n\nAccommodation : Ciner Hotel or Similar"
      },
      {
        "id": "8e20557e-fdb6-4917-9abf-206ed6de3cb7",
        "tour_id": "650fd423-d161-4f36-a15a-28381b5e114a",
        "day_number": 7,
        "title": "Departure",
        "body": "Early this morning, enjoy an unforgettable Sunrise hot air balloon ride over Cappadocia’s magical landscape. Drift above fairy chimneys, colorful valleys, rock formations, and cave villages while watching the sunrise illuminate the region in stunning shades of gold and pink.\n\nAfter the flight, celebrate with a traditional certificate and light refreshment before returning to your hotel for breakfast and check-out.\n\nDepending on your flight time, enjoy some free time for last-minute shopping, relaxing at a local café.\n\nOptional Hot Air Balloon Ride. Depends on weather forecast, it may be any available previous Day."
      }
    ],
