    "meals_dinners": 6,
    "daysList": [
      {
        "id": "4383f319-b494-45a6-86e8-7a4c44275587",
        "tour_id": "3d5e8383-74b2-410a-9c82-5d1912e38348",
        "day_number": 1,
        "title": "Welcome to Fethiye",
        "body": "Welcome to Fethiye !\nToday, we have arranged your hotel reservation for a comfortable start to your journey. You are welcome to check in at any time after your arrival.\nYour welcome meeting at 6 pm. with your tour guide and meet your travel mates in the hotel lobby.\nYour hotel is centrally located, giving you easy access to the city's highlights. For your first evening, we highly recommend visiting a traditional local fish market, where you can experience the authentic flavors of Türkiye and enjoy freshly prepared seafood in a lively local atmosphere. if you are wiling to go dinner with your group, your guide will book a table of you.\n\nAccommodation : Telmessos City Hotel or Similar"
      },
      {
        "id": "ad9937e1-2787-403b-ab27-ec2e50e67385",
        "tour_id": "3d5e8383-74b2-410a-9c82-5d1912e38348",
        "day_number": 2,
        "title": "Ovacık to Faralya Hike ( 12 km)",
        "body": "We check out the hotel and drive to Lycian way starting point. Driver will take all belongings to next hotel. Set off from Ovacık and walk along the start of the Lycian Way. Pass fragrant pine forests, dramatic cliffs, and panoramic views over Butterfly Valley before arriving in the quiet village of Faralya until the hotel.\n\nimportant Note : Summer is extremely hot. We can start the day very early June - July - August. Your guide will decide it.\n\nAccommodation : Casa di Pietta hotel or Similar\nMeal : Breakfast"
      },
      {
        "id": "de92b1ef-7873-4089-a2c9-16d28b389ce8",
        "tour_id": "3d5e8383-74b2-410a-9c82-5d1912e38348",
        "day_number": 3,
        "title": "Faralya to Kabak Hike ( 12 km)",
        "body": "You start high above the sea in Faralya, with sweeping views over the cliffs near Butterfly Valley. The trail quickly pulls you into nature quiet pine forests, rocky paths, and open ridgelines with constant views of the Mediterranean.\n\nAccommodation : Casa Di Pieta or Similar in Kabak\nMeal : Breakfast"
      },
      {
        "id": "cb0564c5-450f-424c-be13-7414319fb48d",
        "tour_id": "3d5e8383-74b2-410a-9c82-5d1912e38348",
        "day_number": 4,
        "title": "Kabak to Alinca ( Sarnic ) (12 km)",
        "body": "The hike from Kabak Valley to Alınca (Sarnıç area) is one of the most challenging but breathtaking sections of the Lycian Way. It’s famous for its steep ascent and incredible “balcony” views over the coastline.\n\nAccommodation : Golden light hotel hotel patara or Similar\nMeal : Breakfast"
      },
      {
        "id": "51beb9ef-4c56-4552-8056-bedfb710d767",
        "tour_id": "3d5e8383-74b2-410a-9c82-5d1912e38348",
        "day_number": 5,
        "title": "Alinca to Sidyma ( 10-12 km)",
        "body": "The hike from Alınca to Sidyma is a quieter, more historical stretch of the Lycian Way. Compared to the dramatic Kabak climb, this day feels more remote, rural, and culturally rich, with ruins appearing right inside a living village.\n\nAccommodation : Golden Light House Patara hotel or Similar\nMeal : Breakfast"
      },
      {
        "id": "e7f64ded-9f74-4696-a988-f78c071acf17",
        "tour_id": "3d5e8383-74b2-410a-9c82-5d1912e38348",
        "day_number": 6,
        "title": "Private Boat Trip in Kekova",
        "body": "Relax after days of hiking with a full-day boat trip in the Kekova region. Swim in hidden coves, explore the sunken ruins of an ancient Lycian city, and enjoy a freshly prepared lunch onboard.\n\nAccommodation : Hebesos Hotel Kas or Similar\nMeal : Breakfast ( included ) | Lunch ( included )"
      },
      {
        "id": "4cf53ed5-e0de-4acc-b9a6-bb906ead66c9",
        "tour_id": "3d5e8383-74b2-410a-9c82-5d1912e38348",
        "day_number": 7,
        "title": "DEPARTURE DAY",
        "body": "As you embark on your journey home, may the memories you've gathered during our trip stay with you like treasures in your heart. \n\nSafe travels and may your path ahead be as enriching and joyful as your time here. Until we meet again, cherish the moments and carry a piece of Turkey's spirit with you wherever you go.\n\nFarewell and best wishes for your future adventures!\n\nWarm regards\n\nAGT GROUP LLC TEAM"
      }
    ],
