    "slug": "6-day-istanbul-adventure-culture-nature-sea",
    "title": "Istanbul Adventure : Hike, Bike & Kayak",
    "code": "WTE-9078",
    "summary": "Experience Istanbul beyond the ordinary on this active 6-day journey blending history, outdoor adventure, and authentic local traditions. Enjoy a traditional Ottoman welcome dinner before exploring the architectural legacy of Mimar Sinan, including the magnificent Süleymaniye Mosque.",
    "description": "Experience Istanbul beyond the ordinary on this active 6-day journey blending history, outdoor adventure, and authentic local traditions. Enjoy a traditional Ottoman welcome dinner before exploring the architectural legacy of Mimar Sinan, including the magnificent Süleymaniye Mosque.\n\nRelax with a centuries-old Turkish bath ritual at Çemberlitaş Hamamı, then escape to the peaceful Princes' Islands for a scenic biking experience on Büyükada.\n\nPaddle between Europe and Asia during a guided sea kayaking adventure on the iconic Bosphorus, and hike through the lush trails of Belgrad Forest.\n\nPerfect for active travelers seeking culture, nature, and unforgettable perspectives of Istanbul.",
