    "daysList": [
      {
        "id": "42ca06fa-84d1-493e-9204-2966937aa67a",
        "tour_id": "55cdd7c9-1296-4483-baf1-809f8a6c98c5",
        "day_number": 1,
        "title": "Arrival & Traditional Ottoman Welcome Dinner",
        "body": "Upon arrival in Istanbul, private transfer to your hotel.\n\nWe have a welcome meeting at 6pm. After welcome meeting, begin your journey with a traditional Ottoman-style welcome dinner. Enjoy refined flavors inspired by imperial palace cuisine in a historic setting — a perfect introduction to Turkish hospitality and culinary heritage.\n\nOvernight in Istanbul."
      },
      {
        "id": "36fe3e2a-333c-49ce-ada6-646ecd8306f4",
        "tour_id": "55cdd7c9-1296-4483-baf1-809f8a6c98c5",
        "day_number": 2,
        "title": "Architect Sinan’s Path & Turkish Hamam Ritual",
        "body": "Discover the architectural legacy of the legendary Ottoman master Mimar Sinan.\nWalk through historic districts while visiting some of his most impressive works, including the magnificent Süleymaniye Mosque overlooking the Golden Horn and continue with Şehzade Mosque, Mihriman Sultan Mosque, Valens Aqueduct, Rüstem Pasha mosque, Spice Market. Learn how Sinan shaped the skyline of Istanbul and defined classical Ottoman architecture.\nIn the afternoon, experience a traditional Turkish bath ritual at the historic Çemberlitaş Hamamı — a centuries-old cleansing and relaxation ceremony combining steam, exfoliation, and foam massage.\nOvernight in Istanbul."
      },
      {
        "id": "fa011372-3d27-4e95-b68e-328b4e2fb189",
        "tour_id": "55cdd7c9-1296-4483-baf1-809f8a6c98c5",
        "day_number": 3,
        "title": "Princes’ Islands Escape & Biking Adventure",
        "body": "Escape the city crowds with a ferry ride to the serene Princes' Islands.\n\nOn Büyükada, explore charming wooden mansions and pine-lined roads by bicycle. Ride along scenic coastal paths, stop for panoramic viewpoints, and enjoy a relaxed seaside lunch.\n\nReturn to Istanbul in the late afternoon.\n\nOvernight in Istanbul."
      },
      {
        "id": "d3da5473-2038-43e4-9481-50c8c4ac9215",
        "tour_id": "55cdd7c9-1296-4483-baf1-809f8a6c98c5",
        "day_number": 4,
        "title": "Bosphorus Sea Kayaking: Between Two Continents",
        "body": "Start your morning with an unforgettable guided kayaking experience on the legendary Bosphorus.\n\nPaddle between Europe and Asia, gliding past Ottoman waterfront mansions and enjoying unique views of the city skyline from sea level. Depending on conditions, you may paddle near landmarks such as Dolmabahçe Palace and beneath the iconic Bosphorus Bridge.\n\nA safety briefing and professional guide ensure a secure and enjoyable experience. Suitable for beginners in calm-weather conditions.\n\nAfternoon at leisure.\n\nOvernight in Istanbul."
      },
      {
        "id": "8bb865c7-8f32-40dd-83a8-3e1c26e01fe7",
        "tour_id": "55cdd7c9-1296-4483-baf1-809f8a6c98c5",
        "day_number": 5,
        "title": "Belgrad Forest Hiking Experience",
        "body": "Today, trade the urban landscape for nature with a guided hike in Belgrad Forest.\n\nFollow shaded woodland trails, breathe fresh air, and discover Istanbul’s green side. The hike is moderate and suitable for active travelers, with scenic breaks along lakes and historic aqueducts.\n\nReturn to the city in the afternoon.\n\nFarewell dinner (optional).\n\nOvernight in Istanbul."
      },
      {
        "id": "b1dce59e-8102-4940-8cf6-8fd77732ac42",
        "tour_id": "55cdd7c9-1296-4483-baf1-809f8a6c98c5",
        "day_number": 6,
        "title": "Departure",
        "body": "As you embark on your journey home, may the memories you're gathered during our trip stay with you like treasures in your heart.\n\nOur team will ensure you have all the details for your onward journey, whether you're heading to the airport or continuing your travels.  Safe travels and thank you for joining us on this incredible adventure !\n\nFarewell and Best wishes for your future adventures!\n\nWe wish to see you again in another great Atlas Global Tours."
      }
    ],
