        "day_number": 9,
        "title": "MIRISSA → GALLE DUTCH FORT → BENTOTA",
        "body": "After breakfast, follow Sri Lanka’s beautiful southern coastline to Galle. Explore the UNESCO-listed Galle Fort, where colonial architecture, charming streets, and ocean views blend to create one of the island’s most captivating destinations.\n\n\n\nLater, continue to the tranquil beach town of Bentota. Upon arrival, check in to your hotel and spend the rest of the day relaxing by the beach, soaking up the peaceful coastal atmosphere.\n\n\n\nACCOMMODATION: Wunderbar Beach Hotel (4 Star) Or Similar\n\n\n\nMEALS: Breakfast\n\n\n\nACTIVITIES: Galle Fort, Lighthouse, Bentota Beach\n\n\n\nPHYSICAL RATING: Low"
