    "daysList": [
      {
        "id": "day-immersive-jordan-1",
        "tour_id": "immersive-jordan",
        "day_number": 1,
        "title": "Amman City - Welcome Day",
        "body": "Arrive in Amman. We have Welcome Meeting at 2 pm Meet with your guide and travel mates. We are Embark on a captivating Jordan tour, starting in Amman with visit to the Citadel and Roman Theater. Get ready for an orientation walk through the city’s lively streets. Discover local cafes, markets, and the historic charm of the Jordanian capital. Evening at leisure.\n\n\n\nIn the evening, savor a street food experience featuring Jordanian favorites such as hummus, falafel, and kunafa — a perfect introduction to the flavors of Amman.\n\n\n\nWe have Complimentary arrival transfer today."
      },
      {
        "id": "day-immersive-jordan-2",
        "tour_id": "immersive-jordan",
        "day_number": 2,
        "title": "Jerash, Ajloun & Amman Cooking Class",
        "body": "After a delicious breakfast, drive to Jerash (approximately one hour) to explore one of the best-preserved ancient Roman cities in the world. Wander through the Oval Plaza, the Temple of Artemis, the North Theatre, and the Colonnaded Street, admiring the grandeur of this archaeological treasure.\n\n\n\nEnjoy a traditional Jordanian lunch at a local restaurant near Jerash before continuing to Ajloun Castle, a striking 12th-century fortress offering panoramic views of the Jordan Valley. Return to Amman in the evening for an authentic Jordanian cooking class experience, where you’ll learn to prepare and enjoy classic local dishes."
      },
      {
        "id": "day-immersive-jordan-3",
        "tour_id": "immersive-jordan",
        "day_number": 3,
        "title": "Amman to Wadi Rum (UNESCO)",
        "body": "Set out on an unforgettable journey to Wadi Rum, the “Valley of the Moon,” a landscape of breathtaking beauty and ancient history (approximately a 4-hour drive). Upon arrival, embark on a scenic jeep adventure through the desert, visiting iconic sites such as Lawrence’s Spring, the Seven Pillars of Wisdom, dramatic sand dunes, and ancient rock petroglyphs that tell stories of millennia past.\n\n\n\nSavor a packed lunch amid the serene desert scenery, then stop at a Bedouin camp to enjoy traditional tea and experience authentic desert hospitality. As the day ends, watch the sun set over the red sands, painting the landscape in golden hues — a perfect moment to relax and reflect.\n\n\n\nIn the evening, enjoy a traditional Jordanian dinner under the stars, followed by music and dance around the campfire, sharing stories and laughter with the welcoming people of Wadi Rum."
      },
      {
        "id": "day-immersive-jordan-4",
        "tour_id": "immersive-jordan",
        "day_number": 4,
        "title": "Discover the Wonders of Petra",
        "body": "Enjoy breakfast at your desert camp before departing for Petra (approximately a 1.5-hour drive). Upon arrival, prepare your camera and begin your exploration of this UNESCO World Heritage site with your expert Tour Guide. Walk through the Siq, a narrow, winding gorge that opens dramatically to reveal the iconic Treasury (Al-Khazneh) — one of the world’s most magnificent archaeological treasures.\n\n\n\nContinue your journey through Petra’s ancient streets, admiring the royal tombs, monuments, and rock-carved façades that narrate the city’s storied past. For those seeking adventure, hike to the Monastery (Ad-Deir) — a rewarding 1.5-hour climb offering spectacular panoramic views.\n\n\n\nSpend the day immersed in Petra’s timeless beauty, discovering landmarks such as the Pharaoh’s Castle, Triumphal Arch, Amphitheatre, the Siq, and the Treasury, before returning in the evening filled with awe and inspiration."
      },
      {
        "id": "day-immersive-jordan-5",
        "tour_id": "immersive-jordan",
        "day_number": 5,
        "title": " Dead Sea & Shobak Castle",
        "body": "In the morning, drive to Shobak Castle (approximately 1.5 hours), an impressive Crusader fortress perched dramatically on a hilltop. Explore its ancient walls and hidden passages, uncovering stories of medieval battles and resilience, while admiring the sweeping views of the surrounding countryside\n\n\n\nContinue your day by exploring the breathtaking shores of the Dead Sea, the lowest point on earth. Float effortlessly in its buoyant, mineral-rich waters and indulge in a soothing mud bath, renowned for its therapeutic properties. Enjoy a relaxing lunch at a beach resort or local restaurant, taking in panoramic views of this otherworldly landscape."
      },
      {
        "id": "day-immersive-jordan-6",
        "tour_id": "immersive-jordan",
        "day_number": 6,
        "title": "Farewell from Jordan – Until We Meet Again",
        "body": "The Tour Ends where it starts in Amman. \n\n\n\nAs you embark on your journey home, may the memories you&#039;ve gathered during our trip stay with you like treasures in your heart. \n\n\n\nSafe travels and may your path ahead be as enriching and joyful as your time here. Until we meet again, cherish the moments and carry a piece of JORDAN&#039;S spirit with you wherever you go.\n\n\n\nFarewell and best wishes for your future adventures!\n\n\n\nWarm regards\n\n\n\nAGT GROUP LLC TEAM"
      }
    ],
