        "body": "Today, we have a morning flight to Jordan, connecting from Cairo. Your Egyptian guide will say goodbye to you in Cairo, and upon arrival in Jordan, you will meet your new tour guide who will accompany you on the next part of your journey.\n\n\n\nToday is another exciting day as we begin our adventure in Jordan!"
