        "body": "Journey into the Sahara.\n\n\n\nExperience a camel trek across the dunes.\n\n\n\nEnjoy a desert sunset at the Chott el Jerid salt lake.\n\n\n\nOvernight under the stars in a traditional Sahara camp."
