        "title": "Casablanca | Arrival & Coastal Elegance",
        "body": "Welcome to Casablanca. Today welcome meeting at 1 pm. Meet with your travel mates and your tour Leader/Guide. Visit the stunning Hassan II Mosque, stroll the Corniche, and enjoy a seaside welcome dinner featuring fresh Atlantic seafood and Moroccan wines. \n\n\n\nStay in Casablanca tonight."
