      {
        "id": "day-immersive-morocco-2",
        "tour_id": "immersive-morocco",
        "day_number": 2,
        "title": "Rabat | Royal Heritage",
        "body": "Travel to Rabat, Morocco’s refined capital. Discover the Kasbah of the Udayas, Hassan Tower, and Royal Palace gates. Enjoy a home-style lunch hosted by a local family and learn how to prepare traditional mint tea.\n\n\n\nOvernight in Rabat"
      },
      {
        "id": "day-immersive-morocco-3",
        "tour_id": "immersive-morocco",
        "day_number": 3,
        "title": "Chefchaouen | The Blue Pearl",
        "body": "Journey into the Rif Mountains to the enchanting blue-washed town. Wander painted alleyways, meet local artisans, and taste goat cheese, olives, and regional breads. Sunset photography from the Spanish Mosque hill.\n\n\n\nOvernight in Chefchaouen."
      },
      {
        "id": "day-immersive-morocco-4",
        "tour_id": "immersive-morocco",
        "day_number": 4,
        "title": "Fes | Spiritual & Culinary Heart",
        "body": "Morning free for last strolls and photos in Chefchaouen. Drive to Fes, Morocco’s spiritual and cultural heart.\n\n\n\nGuided walk through the medieval medina and tanneries\n\n\n\nOvernight in Fes."
      },
      {
        "id": "day-immersive-morocco-5",
        "tour_id": "immersive-morocco",
        "day_number": 5,
        "title": "Fes | Spiritual & Culinary Heart",
        "body": "Guided walking tour of Fes el-Bali Medina (UNESCO), the world’s largest car-free urban area.\n\n\n\nVisit a pottery cooperative and traditional mosaic workshop. Hands-on cooking class inside a riad: tagine, pastilla, and Moroccan salads. \n\n\n\nEvening Andalusian music performance. \n\n\n\nOvernight in Fes."
      },
      {
        "id": "day-immersive-morocco-6",
        "tour_id": "immersive-morocco",
        "day_number": 6,
        "title": "Midelt | Atlas Mountain Life",
        "body": "Cross cedar forests and Berber villages of the Middle Atlas. Stop to see wild Barbary macaques. In Midelt, enjoy a farm-to-table dinner with local Amazing hosts and learn about mountain traditions.\n\n\n\nOvernight in Midelt."
      },
      {
        "id": "day-immersive-morocco-7",
        "tour_id": "immersive-morocco",
        "day_number": 7,
        "title": "Merzouga & Sahara | Desert Immersion",
        "body": "Enter the golden dunes for a true Sahara experience. Ride camels across sunset sands, then arrive at a luxury desert camp. Dinner under the stars with live Gnawa drums and storytelling by nomads.\n\n\n\nOvernight in Sahara desert Camp"
      },
      {
        "id": "day-immersive-morocco-8",
        "tour_id": "immersive-morocco",
        "day_number": 8,
        "title": "Todra Gorge | Oasis Walks & Berber Encounters",
        "body": "Morning arrival through the palm groves of Tinghir, one of Morocco’s most beautiful desert oases. Guided walk along irrigation channels and mud-brick ksar villages.\n\n\n\nExplore Todra’s towering canyon walls, rising up to 300 meters. Lunch with a local Amazing family featuring fresh bread, olive oil, dates, and tagine.\n\n\n\nAfternoon option: light canyon hike or photography session capturing shifting desert light.\n\n\n\nOvernight in a boutique kasbah lodge near the gorge."
      },
      {
        "id": "day-immersive-morocco-9",
        "tour_id": "immersive-morocco",
        "day_number": 9,
        "title": "Dades Valley | Valleys, Kasbahs & Scenic Routes",
        "body": "Scenic drive along the “Road of a Thousand Kasbahs.” Visit rose-growing villages (seasonal harvest May–June) and women’s cooperatives producing rosewater.\n\n\n\nShort hike through rock formations known as the “Monkey Fingers.” Traditional lunch in a valley guesthouse overlooking dramatic red cliffs.\n\n\n\nCultural stop in a nomadic settlement to learn about desert survival traditions and tea rituals.\n\n\n\nSunset viewpoints over winding mountain roads and layered canyon landscapes."
      },
      {
        "id": "day-immersive-morocco-10",
        "tour_id": "immersive-morocco",
        "day_number": 10,
        "title": "Ait Benhaddou & Atlas Crossing",
        "body": "Travel the legendary Caravan Road. Stop at Ait Benhaddou, a UNESCO-listed earthen village famous for film sets. Cross the High Atlas Mountains with panoramic passes and tea stops.\n\n\n\nOvernight in Ait Benhaddou"
      },
      {
        "id": "day-immersive-morocco-11",
        "tour_id": "immersive-morocco",
        "day_number": 11,
        "title": "Marrakech | Red City Magic",
        "body": "Discover Marrakech’s palaces, gardens, and souks. Highlights include Bahia Palace, Majorelle Garden, and spice markets. Evening food tour through Jemaa el-Fnaa tasting street delicacies like snail soup, msemen, and fresh juices.\n\n\n\nOvernight in Marrakech"
      },
      {
        "id": "day-immersive-morocco-12",
        "tour_id": "immersive-morocco",
        "day_number": 12,
        "title": "Departure Day",
        "body": "As you embark on your journey home, may the memories you&#039;ve gathered during our trip stay with you like treasures in your heart.\n\n\n\nSafe travels and may your path ahead be as enriching and joyful as your time here. Until we meet again, cherish the moments and carry a piece of Morocco&#039;s spirit with you wherever you go.\n\n\n\nFarewell and best wishes for your future adventures!\n\n\n\nWarm regards\n\n\n\nAGT GROUP LLC TEAM"
      }
