        "day_number": 1,
        "title": "MUSCAT CITY - Welcome Day",
        "body": "Arrive in the captivating seaside capital, Muscat, where your journey begins at 1:00 PM with a welcome meeting. Meet your expert tour guide and fellow travelers as you prepare to embark on an unforgettable adventure through the heart of Oman.\n\n\n\nStart your exploration with a visit to the magnificent Sultan Qaboos Grand Mosque, an architectural masterpiece and one of the largest mosques in the world. Continue to the Royal Opera House, a stunning example of Omani elegance and cultural pride.\n\n\n\nAs evening descends, stroll through the lively Mutrah Souq, one of the oldest marketplaces in the Arab world, filled with the scent of frankincense and vibrant displays of traditional crafts and spices.\n\n\n\nConclude your day with a welcome dinner at Kargeen Café, where you’ll savor a delightful blend of traditional Omani and modern cuisine in a beautiful open-air garden setting—a perfect introduction to Oman’s warmth and hospitality."
